using Microsoft.AspNetCore.Mvc;using Sigov.Api.Contracts;using Sigov.Application.Abstractions;using Sigov.Application.Saude.Avancada;
namespace Sigov.Api.Controllers;
[ApiController,Route("api/saude/acs-offline")] public sealed class SaudeAcsOfflineController:SaudeAvancadaControllerBase{readonly ISaudeAcsOfflineService _service;public SaudeAcsOfflineController(ISaudeAcsOfflineService service,ICurrentTenant tenant,ICurrentUser user):base(tenant,user)=>_service=service;
[HttpGet("dashboard")]public async Task<ActionResult<ApiResponse<object>>> Dashboard(CancellationToken ct)=>Resposta<object>(await _service.DashboardAsync(TenantId(),"saude_acs_lote_offline",ct));
[HttpGet("dispositivos")]public async Task<ActionResult<ApiResponse<object>>> Dispositivos([FromQuery]SaudeAvancadaFiltro f,CancellationToken ct)=>Resposta<object>(await _service.ListarAsync(TenantId(),"saude_acs_dispositivo",f,ct));[HttpPost("dispositivos")]public async Task<ActionResult<ApiResponse<long>>> RegistrarDispositivo(SaudeAvancadaOperacaoRequest r,CancellationToken ct)=>Resposta(await _service.CriarAsync(Contexto(),"saude_acs_dispositivo",r,ct));[HttpPost("dispositivos/{id:long}/ativar")]public async Task<ActionResult<ApiResponse<bool>>> Ativar(long id,CancellationToken ct)=>Resposta(await _service.AlterarStatusAsync(Contexto(),"saude_acs_dispositivo",id,"ATIVO",null,ct));[HttpPost("dispositivos/{id:long}/bloquear")]public async Task<ActionResult<ApiResponse<bool>>> Bloquear(long id,CancellationToken ct)=>Resposta(await _service.AlterarStatusAsync(Contexto(),"saude_acs_dispositivo",id,"BLOQUEADO","Bloqueio operacional auditado",ct));
[HttpGet("lotes")]public async Task<ActionResult<ApiResponse<object>>> Lotes([FromQuery]SaudeAvancadaFiltro f,CancellationToken ct)=>Resposta<object>(await _service.ListarAsync(TenantId(),"saude_acs_lote_offline",f,ct));[HttpPost("lotes")]public async Task<ActionResult<ApiResponse<long>>> CriarLote(SaudeAvancadaOperacaoRequest r,CancellationToken ct)=>Resposta(await _service.CriarAsync(Contexto(),"saude_acs_lote_offline",r,ct));[HttpGet("lotes/{id:long}")]public async Task<ActionResult<ApiResponse<object?>>> Lote(long id,CancellationToken ct)=>Resposta<object?>(await _service.ObterAsync(TenantId(),"saude_acs_lote_offline",id,ct));[HttpPost("lotes/{id:long}/sincronizar")]public async Task<ActionResult<ApiResponse<bool>>> Sincronizar(long id,CancellationToken ct)=>Resposta(await _service.AlterarStatusAsync(Contexto(),"saude_acs_lote_offline",id,"SINCRONIZADO",null,ct));[HttpPost("lotes/{id:long}/reprocessar")]public async Task<ActionResult<ApiResponse<bool>>> Reprocessar(long id,CancellationToken ct)=>Resposta(await _service.AlterarStatusAsync(Contexto(),"saude_acs_lote_offline",id,"AGUARDANDO_SINCRONIZACAO","Reprocessamento auditado",ct));
[HttpGet("inconsistencias")]public async Task<ActionResult<ApiResponse<object>>> Inconsistencias([FromQuery]SaudeAvancadaFiltro f,CancellationToken ct)=>Resposta<object>(await _service.ListarAsync(TenantId(),"saude_acs_inconsistencia",f,ct));[HttpGet("geopontos")]public async Task<ActionResult<ApiResponse<object>>> Geopontos([FromQuery]SaudeAvancadaFiltro f,CancellationToken ct)=>Resposta<object>(await _service.ListarAsync(TenantId(),"saude_acs_geoponto",f,ct));[HttpGet("producao")]public async Task<ActionResult<ApiResponse<object>>> Producao([FromQuery]SaudeAvancadaFiltro f,CancellationToken ct)=>Resposta<object>(await _service.ListarAsync(TenantId(),"saude_acs_sincronizacao",f,ct));[HttpGet("relatorios/resumo")]public async Task<ActionResult<ApiResponse<object>>> Resumo(CancellationToken ct)=>Resposta<object>(await _service.DashboardAsync(TenantId(),"saude_acs_sincronizacao",ct));[HttpGet("relatorios/exportar-csv")]public async Task<IActionResult> Csv(CancellationToken ct)=>File(await _service.ExportarCsvAsync(TenantId(),"saude_acs_sincronizacao",ct),"text/csv","producao-acs.csv");}
